using MediatR; using InventorySystem.Application.Features.Warehouses.Commands; using InventorySystem.Application.Features.Warehouses.Queries; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace InventorySystem.API.Controllers;
[ApiController][Route("api/warehouses")] public class WarehousesController(IMediator m):ControllerBase { [HttpGet] public async Task<IActionResult> Get([FromQuery]string? search)=>Ok(await m.Send(new GetWarehousesQuery(search))); [HttpGet("{id:int}")] public async Task<IActionResult> GetById(int id)=>Ok(await m.Send(new GetWarehouseByIdQuery(id))); [HttpPost][Authorize(Roles="Admin,Manager")] public async Task<IActionResult> Post(CreateWarehouseCommand c)=>Ok(new{id=await m.Send(c)}); [HttpPut("{id:int}")][Authorize(Roles="Admin,Manager")] public async Task<IActionResult> Put(int id,UpdateWarehouseCommand c){ if(id!=c.Id) return BadRequest(new{error="Id mismatch."}); await m.Send(c); return NoContent(); } [HttpDelete("{id:int}")][Authorize(Roles="Admin,Manager")] public async Task<IActionResult> Delete(int id){ await m.Send(new DeleteWarehouseCommand(id)); return NoContent(); } }
